-- Delivery priced by provider and place (owner, 2 Nov 2026): a customer chooses who carries it and a place under them, each
-- place has a price, and the fee is paid with the order before delivery. Staff correct prices in Settings > Delivery options.
--
-- THESE PRICES ARE ESTIMATES. Sources, Nov 2026: Easy Coach (KSh 300 up to 7 kg), ENA (250 up to 7 kg) and Modern Coast (350 for
-- 5 kg) as reported April 2025; Pickup Mtaani's undated rate card (70, 120, 240 to 290); older G4S and Wells Fargo tables (first
-- 5 kg about 420 Nyeri, 500 Kisumu, 650 Mombasa); blog ranges for Nairobi boda delivery (150 to 500). Metros, 2NK, Kukena, Meru
-- Nissan, Unique Shuttle and Luxury publish nothing, so those prices and routes are judged by distance. fare_confirmed stays false
-- until staff save a price.
ALTER TABLE transport_operator
    ADD COLUMN kind VARCHAR(10) NOT NULL DEFAULT 'METRO' CHECK (kind IN ('METRO', 'RIDER', 'OUTSIDE'));

