-- The next-day "did you receive your order?" list: when an order left, and when staff asked.
ALTER TABLE customer_order
    ADD COLUMN dispatched_at TIMESTAMP WITH TIME ZONE,
    ADD COLUMN received_check_sent_at TIMESTAMP WITH TIME ZONE;
UPDATE customer_order SET dispatched_at = updated_at WHERE status IN ('DISPATCHED', 'DELIVERED');
